import unittest
from unittest.mock import patch, MagicMock

class ChemistLabTest(unittest.TestCase):
    @patch('module.query_chemist_lab')
    def test_query_chemist_lab_success(self, mock_query):
        mock_query.return_value = {'id': '123', 'name': 'John Doe', 'address': '123 Main St', 'contact': '123-456-7890'}
        response = query_chemist_lab('123')
        self.assertEqual(response, {'id': '123', 'name': 'John Doe', 'address': '123 Main St', 'contact': '123-456-7890'})

    @patch('module.query_chemist_lab')
    def test_query_chemist_lab_failure(self, mock_query):
        mock_query.return_value = None
        with self.assertRaises(Exception) as context:
            query_chemist_lab('456')
        self.assertIn('Chemist or Lab does not exist', str(context.exception))

    @patch('module.delete_chemist_lab')
    @patch('module.check_open_requests')
    def test_delete_chemist_lab_success(self, mock_check, mock_delete):
        mock_check.return_value = False
        mock_delete.return_value = True
        response = delete_chemist_lab('123')
        self.assertTrue(response)

    @patch('module.delete_chemist_lab')
    @patch('module.check_open_requests')
    def test_delete_chemist_lab_failure(self, mock_check, mock_delete):
        mock_check.return_value = True
        mock_delete.return_value = False
        with self.assertRaises(Exception) as context:
            delete_chemist_lab('123')
        self.assertIn('Chemist or Lab has open Prescription Requests - cannot delete', str(context.exception))

class SymptomTest(unittest.TestCase):
    @patch('module.add_symptom')
    def test_add_symptom_success(self, mock_add):
        mock_add.return_value = True
        response = add_symptom('123', 'Symptom Description')
        self.assertTrue(response)

    @patch('module.update_symptom')
    def test_update_symptom_success(self, mock_update):
        mock_update.return_value = True
        response = update_symptom('123', 'Updated Symptom Description')
        self.assertTrue(response)

    @patch('module.update_symptom')
    def test_update_symptom_failure(self, mock_update):
        mock_update.return_value = False
        with self.assertRaises(Exception) as context:
            update_symptom('456', 'Updated Symptom Description')
        self.assertIn('Symptom does not exist', str(context.exception))

class PatientProfileTest(unittest.TestCase):
    @patch('module.register_patient')
    def test_register_patient_success(self, mock_register):
        mock_register.return_value = {'id': '123', 'name': 'John Doe', 'age': 30, 'sex': 'Male', 'address': '123 Main St', 'contact': '123-456-7890'}
        response = register_patient('John Doe', '30', 'Male', '123 Main St', '123-456-7890')
        self.assertEqual(response, {'id': '123', 'name': 'John Doe', 'age': 30, 'sex': 'Male', 'address': '123 Main St', 'contact': '123-456-7890'})

    @patch('module.register_patient')
    def test_register_patient_failure(self, mock_register):
        mock_register.return_value = None
        with self.assertRaises(Exception) as context:
            register_patient('John Doe', '30', 'Male', '123 Main St', '123-456-7890')
        self.assertIn('Invalid username/password', str(context.exception))

if __name__ == '__main__':
    unittest.main()
